"""Shared path handling for :mod:`wsparse`.

The sparse-file FSCTLs only apply to regular files on a volume that supports
sparse files.  Handing one of the public entry points something else -- a
directory, for instance -- is a permanent condition rather than a transient
I/O error, so it is reported as ``kind="unsupported"``.
"""

import os
import stat

from ._winapi import is_windows
from .errors import WSParseError


def resolve(path):
    """Normalise ``path`` into a ``str`` usable with the Win32 wide calls."""
    try:
        path = os.fspath(path)
    except TypeError as exc:
        raise WSParseError(
            "path must be a string or os.PathLike, got %r" % (path,), kind="badarg"
        ) from exc
    if isinstance(path, bytes):
        path = os.fsdecode(path)
    if not isinstance(path, str):
        raise WSParseError(
            "path must be a string or os.PathLike, got %r" % (path,), kind="badarg"
        )
    return path


def require_windows(path=None):
    """Raise ``unsupported`` when the platform has no sparse-file concept."""
    if not is_windows():
        raise WSParseError(
            "sparse files are a Windows/NTFS concept; this platform has none",
            kind="unsupported",
            path=path,
        )


def stat_existing(path):
    """``os.stat`` ``path``, reporting a missing path as ``kind="os"``."""
    try:
        return os.stat(path)
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc


def require_regular_file(path, info=None):
    """Reject anything that cannot carry the sparse attribute.

    Directories, devices, pipes and the like have no sparse semantics, so the
    sparse-file entry points report them as ``kind="unsupported"``.
    """
    if info is None:
        info = stat_existing(path)
    mode = info.st_mode
    if stat.S_ISDIR(mode):
        raise WSParseError(
            "a directory cannot carry the sparse attribute",
            kind="unsupported",
            path=path,
        )
    if not stat.S_ISREG(mode):
        raise WSParseError(
            "only regular files support sparse-file operations",
            kind="unsupported",
            path=path,
        )
    return info

"""Allocated-range reporting for sink files."""

from . import _winapi
from ._paths import require_regular_file, require_windows, resolve, stat_existing
from .errors import WSParseError


def _normalise(raw, size):
    """Clamp, order and merge the raw ranges reported by the file system."""
    clipped = []
    for offset, length in raw:
        if length <= 0 or offset >= size:
            continue
        if offset < 0:
            length += offset
            offset = 0
        if length <= 0:
            continue
        if offset + length > size:
            length = size - offset
        if length > 0:
            clipped.append((offset, length))

    clipped.sort(key=lambda item: item[0])

    merged = []
    for offset, length in clipped:
        if merged and offset <= merged[-1][0] + merged[-1][1]:
            previous_offset, previous_length = merged[-1]
            end = max(previous_offset + previous_length, offset + length)
            merged[-1] = (previous_offset, end - previous_offset)
        else:
            merged.append((offset, length))
    return merged


def allocated_ranges(path):
    """Return ``[(offset, length), ...]`` of the byte ranges backed by clusters.

    The transfer layer uses this to decide which parts of a sink still have to
    be fetched: a range that is already allocated is on disk, everything else
    is a hole that still needs data.  The list is ordered by ``offset``, the
    ranges never overlap, and every range lies inside the file's logical
    length.

    A file consisting only of holes reports an empty list; a dense file reports
    a single range covering its whole length.
    """
    path = resolve(path)
    info = stat_existing(path)
    require_windows(path)
    require_regular_file(path, info)

    size = info.st_size
    if size <= 0:
        return []

    handle = _winapi.open_file(path, write=False, create=False)
    try:
        size = _winapi.file_size(handle, path=path)
        if size <= 0:
            return []
        sparse = bool(
            getattr(info, "st_file_attributes", 0) & _winapi.SPARSE_ATTRIBUTE
        )
        try:
            raw = _winapi.query_allocated_ranges(handle, size, path=path)
        except WSParseError as exc:
            if sparse or exc.kind != "unsupported":
                raise
            # A plain file on a volume that does not implement the query is
            # dense by definition: all of it is backed by clusters.
            return [(0, size)]
        return _normalise(raw, size)
    finally:
        _winapi.close_handle(handle)

